from __future__ import absolute_import
from taf.selenium.sbts.pages import v25r1, v24r3


class BtsStatus(v25r1.bts_status.BtsStatus):

    def __init__(self, driver):
        super(BtsStatus, self).__init__(driver)
        self._site_view = SiteViewPage(driver)


class SiteViewPage(v25r1.bts_status.SiteViewPage):

    def __init__(self, driver):
        super(SiteViewPage, self).__init__(driver)
        self._view_panel = SiteViewPageViewPanel(driver)
        self._detail_panel = SiteViewPageDetailPanel(driver)

    def get_nr_position_cell_info(self, cell_idx, timeout=10):
        self._view_panel._click_nr_position_cell_by_cell_index(cell_idx)
        return self._detail_panel._extract_nr_position_cell_info(cell_idx, timeout)


class SiteViewPageViewPanel(v24r3.bts_status.SiteViewPageViewPanel):

    _NR_POSITION_CELL_ICON_XPATH_TEMPLATE = '//div[@class="cell-nrpos-grid-element"]//div[@title="{}"]'

    def _click_nr_position_cell_by_cell_index(self, cell_idx):
        cell_xpath = self._NR_POSITION_CELL_ICON_XPATH_TEMPLATE.format(cell_idx)
        self.click_element_by_xpath(cell_xpath)


class SiteViewPageDetailPanel(v24r3.bts_status.SiteViewPageDetailPanel):

    _NR_POSITION_CELL_DETAILS_XPATH = '//div[@class="header"]//span[text()="NRPOSCELL-{}"]'

    def _extract_nr_position_cell_info(self, cell_idx, timeout):
        cell_details_xpath = self._NR_POSITION_CELL_DETAILS_XPATH.format(cell_idx)
        self.wait_for_visibility_by_xpath(cell_details_xpath, timeout)
        return self.get_detail_info_table()
